import { useState } from 'react';
import SettingsSidebar from './SettingsSidebar';

interface NavLink {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
}

interface User {
  name: string;
  email: string;
}

const mockData: { user: User; links: NavLink[] } = {
  user: {
    name: 'Alex Johnson',
    email: 'alex.johnson@company.com',
  },
  links: [
    {
      id: 'profile',
      label: 'Profile',
      icon: UserIcon,
    },
    {
      id: 'billing',
      label: 'Billing',
      icon: CreditCardIcon,
    },
    {
      id: 'team',
      label: 'Team',
      icon: TeamIcon,
    },
    {
      id: 'notifications',
      label: 'Notifications',
      icon: BellIcon,
    },
    {
      id: 'security',
      label: 'Security',
      icon: LockIcon,
    },
  ],
};

export function App() {
  const [activeLink, setActiveLink] = useState<string>('profile');
  const { user, links } = mockData;

  return (
    <div className="flex h-screen bg-gray-50">
      <SettingsSidebar
        links={links}
        activeLink={activeLink}
        onLinkClick={setActiveLink}
        user={user}
      />
    </div>
  );
}
```

