### SettingsSidebar.tsx
```tsx
import { useState } from 'react';
import { UserIcon, CreditCardIcon, BellIcon, LockIcon } from 'lucide-react';

type NavLink = {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
};

type Props = {
  links: NavLink[];
  activeLink: string;
  onLinkClick: (id: string) => void;
  user: {
    name: string;
    email: string;
  };
};

export function SettingsSidebar({ links, activeLink, onLinkClick, user }: Props) {
  return (
    <div className="w-64 flex flex-col bg-white border-r border-gray-200 h-full">
      <div className="p-6 flex flex-col space-y-4">
        {links.map((link) => (
          <button
            key={link.id}
            onClick={() => onLinkClick(link.id)}
            className={`flex items-center space-x-3 p-3 rounded-lg transition-all duration-200 w-full text-left ${
              activeLink === link.id
                ? 'bg-accent text-white'
                : 'text-gray-700 hover:bg-gray-100'
            }`}
          >
            <link.icon className="w-5 h-5" />
            <span className="font-medium">{link.label}</span>
          </button>
        ))}
      </div>
      <div className="p-6 border-t border-gray-100">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 rounded-full bg-gradient-to-br from-blue-500 to-teal-400 flex items-center justify-center">
            <span className="text-white font-bold text-sm">A</span>
          </div>
          <div>
            <p className="font-medium text-gray-900">{user.name}</p>
            <p className="text-sm text-gray-500">{user.email}</p>
          </div>
        </div>
      </div>
    </div>
  );
}
```

